def solve_any(inp,bgc,diag=False):
    H,W=len(inp),len(inp[0])
    out=[row[:] for row in inp]
    anom=[(a,b,int(inp[a][b])) for a in range(H) for b in range(W) if inp[a][b]!=bgc]
    for a in range(H):
        for b in range(W):
            if inp[a][b]==bgc:
                fill=False
                # ortho lines
                for q,r in itertools.combinations(anom,2):
                    if q[0]==r[0]==a and min(q[1],r[1])<b<max(q[1],r[1]): fill=True;break
                if not fill:
                    for q,r in itertools.combinations(anom,2):
                        if q[1]==r[1]==b and min(q[0],r[0])<a<max(q[0],r[0]): fill=True;break
                if diag:
                    for q,r in itertools.combinations(anom,2):
                        dr=q[0]-r[0]; dc=q[1]-r[1]
                        if abs(dr)==abs(dc):
                            # p between q,r on the diagonal
                            if (a-q[0])*(a-r[0]>=-0) or True: pass
                            on=(a>min(q[0],r[0]) and a<max(q[0],r[0]) and b>min(q[1],r[1]) and b<max(q[1],r[1]))
                            step=(1 if (q[0]<r[0]) else -1)
                            on_d=((a-step*0)>=0)
                            # strict: steps integer
                            da=a-min(q[0],r[0]); db=b-min(q[1],r[1])
                            if da==db and da>0:
                                sgn=(1 if (q[0]<r[0]) else -1)
                                ok=min(q[0],r[0])+sgn*da<=a<=max(q[0],r[0])+0
                                if on_d: fill=True;break
                if fill: out[a][b]=1
    return out

