# Hypothesis H: a bg cell becomes 1 iff it lies in the interior of the minimal axis-aligned rectangle (inclusive edges except endpoints) spanned by exactly two anomalies (no third anomaly on those edges), OR equivalently lies on a straight line segment between two anomalies.
# More simply: cell c is on segment ab (collinear & between). Test pairwise segments (all pairs incl diagonal?). Try collinear only.
def on_segment(c, a, b):
    return ((c==a) or (c==b)) and False
def test_rule(i,o):
    h,w=len(i),len(i[0])
    cnt=Counter(y for r in i for y in r); bg=cnt.most_common(1)[0][0]
    an=[(r,c,int(i[r][c])) for r in range(h) for c in range(w) if i[r][c]!=bg]
    fcs=set((r,c) for r in range(h) for c in range(w) if o[r][c]==1 and i[r][c]==bg)
    pred=set()
    import math
    for p,q in itertools.combinations(an,2):
        # horizontal or vertical
        if p[0]==q[0]:
            for c_ in range(min(p[1],q[1])+1,max(p[1],q[1])):
                pred.add((p[0],c_))
        elif p[1]==q[1]:
            for r_ in range(min(p[0],q[0])+1,max(p[0],q[0])):
                pred.add((r_,p[1]))
    # diagonal collinear pairs
    for p,q in itertools.combinations(an,2):
        dr=p[0]-q[0]; dc=p[1]-q[1]
        g=math.gcd(abs(dr),abs(dc)) if (dr or dc) else 1
        if g!=g: pass
        for k in range(1,g):
            rr,q_=q[0]+dr//g*k, q[1]+dc//g*k
            pred.add((rr,q_))
    return fcs<=pred, len(fcs), len(pred)
