    wall=np.zeros((h,w),bool)
    for r in range(h):
        for c in range(w):
            if i[r][c]!=bg: wall[r][c]=True
    fcs=[(r,c) for r in range(h) for c in range(w) if o[r][c]==1 and i[r][c]==bg]
    # flood fill outside the wall set
    seen=np.zeros_like(wall,bool); stack=[]
    for r in range(h):
        for c in range(w):
            if not wall[r][c] and not seen[r][c]:
                seen[r][c]=True; stack.append((r,c))
                while stack:
                    a,b=stack.pop()
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            p,q=a+dr,b+dc
                            if 0<=p<h and 0<=q<w and not wall[p][q] and not seen[p][q]:
                                seen[p][q]=True; stack.append((p,q))
    fillset=set(map(tuple,fcs))
    unvis={tuple(r) for r in range(h) for c in range(w) if not wall[tuple((r,c))] for r,c,_ in [(x,y,z) for x,y,z in [(r,c,i[r][c]) for r in range(h) for c in range(w)] if True]}
    return fcs, seen, fillset
