import numpy as np, itertools
from collections import Counter, deque
def solve_rule(i,bg):
    h,w=len(i),len(i[0])
    an=[(r,c) for r in range(h) for c in range(w) if i[r][c]!=bg]
    A=set(an)
    # flood fill bg cells that are NOT 4-connected to any anomaly and not connected to the grid border
    out=i[:]
    vis=np.zeros((h,w),bool)
    st=deque()
    for r in range(h):
        for c in range(w):
            if i[r][c]==bg and not vis[r][c]:
                vis[r][c]=True; st.append((r,c))
                while st:
                    a,b=st.popleft()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        p,q=a+da,b+db
                        if 0<=p<h and 0<=q<w and not vis[p][q] and i[p][q]==bg:
                            vis[p][q]=True; st.append((p,q))
    border_cells={(r,c) for r in (0,h-1) for c in range(w)} | {(r,c) for r in range(h) for c in (0,w-1)}
    # interior non-anom cells enclosed by wall: those whose 8-neighborhood is blocked? use BFS from anomalies through bg
    anom_reach=np.zeros((h,w),bool)
    q=deque(); seen=np.zeros((h,w),bool)
    for r,c in an:
        seen[r][c]=True; q.append((r,c))
    while q:
        a,b=q.popleft()
        for da in(-1,0,1):
            for db in(-1,0,1):
                p,q_=a+da,b+db
                if 0<=p<h and 0<=q_<w and i[p][q_]==bg and not seen[p][q_]:
                    seen[p][q_]=True; anom_reach[p][q_]=True; q.append((p,q_))
    # fills = bg cells NOT reached by anomaly AND not touching border via bg path? 
    # try: unreachable-from-any-anomaly bg cells that also touch grid border?
    return anom_reach
